mapper.sql:
r.wms_tenant_id = #{wmsTenantId}
AND r.fee_type = 'SHIPPING'

    AND r.bill_month >= #{monthStart}


    AND r.bill_month <= #{monthEnd}


    AND r.erp_tenant_id = #{erpTenantId}

mapper.select:
SELECT r.id, r.bill_month AS billMonth, r.logistics_product_id AS productId, t.tenant_name AS ownerName, o.outbound_no AS outboundNo, r.tracking_no AS trackingNo, r.amount, DATE_FORMAT(r.create_time, '%Y-%m-%d %H:%i:%s') AS createTime FROM wms_client_billing_record r LEFT JOIN sys_tenant t ON t.id = r.erp_tenant_id LEFT JOIN wms_sales_outbound_order o ON o.id = r.outbound_order_id
AND r.logistics_product_id = #{productId}
ORDER BY r.id DESC
